import { precacheAndRoute } from 'workbox-precaching';
import { registerRoute } from 'workbox-routing';
import { CacheFirst, NetworkFirst, StaleWhileRevalidate } from 'workbox-strategies';
import { ExpirationPlugin } from 'workbox-expiration';
import { BackgroundSyncPlugin } from 'workbox-background-sync';

// Disable spammy workbox logs in development
self.__WB_DISABLE_DEV_LOGS = true;

// Precache static assets generated by Vite
precacheAndRoute(self.__WB_MANIFEST || []);

// Cloudinary Image Cache (CacheFirst)
registerRoute(
  ({ url }) => url.origin === 'https://res.cloudinary.com',
  new CacheFirst({
    cacheName: 'cloudinary-images',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 100,
        maxAgeSeconds: 30 * 24 * 60 * 60, // 30 Days
      }),
    ],
  })
);

// API caching for messages and users (NetworkFirst)
registerRoute(
  ({ url }) => url.pathname.startsWith('/api/messages') || url.pathname.startsWith('/api/auth'),
  new NetworkFirst({
    cacheName: 'api-cache',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 50,
        maxAgeSeconds: 24 * 60 * 60, // 1 Day
      }),
    ],
  })
);

// Background Sync for failed outbound messages
const bgSyncPlugin = new BackgroundSyncPlugin('outbound-messages-queue', {
  maxRetentionTime: 24 * 60, // Retry for up to 24 Hours
});

registerRoute(
  ({ url, request }) => url.pathname.includes('/api/messages/send') && request.method === 'POST',
  new NetworkFirst({
    plugins: [bgSyncPlugin],
  })
);

// Listen for push events (Phase 2 stub)
self.addEventListener('push', (event) => {
  if (event.data) {
    const data = event.data.json();
    const options = {
      body: data.body,
      icon: '/pwa-192x192.png',
      badge: '/masked-icon.svg',
      data: data,
    };
    event.waitUntil(self.registration.showNotification(data.title, options));
  }
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      if (clientList.length > 0) {
        let client = clientList[0];
        for (let i = 0; i < clientList.length; i++) {
          if (clientList[i].focused) {
            client = clientList[i];
          }
        }
        // Navigate to home first so cold-start hook can handle from clean state
        client.navigate('/');
        return client.focus();
      }
      return clients.openWindow('/');
    })
  );
});

// Handle navigation requests: always serve the app shell (index.html)
// This prevents Chrome from restoring stale deep-route pages on PWA cold start
registerRoute(
  ({ request }) => request.mode === 'navigate',
  new NetworkFirst({
    cacheName: 'navigation-cache',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 1,
        maxAgeSeconds: 24 * 60 * 60, // 1 Day
      }),
    ],
  })
);

// Allow the SW to skip waiting and claim clients immediately
self.addEventListener('install', () => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    Promise.all([
      self.clients.claim(),
      // Clean up old runtime caches to prevent stale data after updates
      caches.keys().then((cacheNames) => {
        return Promise.all(
          cacheNames
            .filter((name) => name !== 'workbox-precache-v2' && name.startsWith('workbox-'))
            .map((name) => caches.delete(name))
        );
      }),
    ])
  );
});
